      "range": [
        -3,
        3,
        0.25
      ],
      "default": 1
    },
    {
      "id": "layoutMode",
      "type": "toggle",
      "teaches": "That the stacked view makes lengths easy to compare, while the shared-tail overlay makes it obvious that every scalar multiple lies on one line through the tail — same ray for positive k, opposite ray for negative k.",
      "label": "Arrow layout",
