<span style="display:flex;gap:6px;align-items:center;margin-top:6px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="flex:1;text-align:center;font-size:11px;color:#333"></span>
  <button onclick="nextStep()">▶</button>
</span>
<p id="demoNarration" style="margin:0;font-size:12px;line-height:1.45;color:#333"></p>
<button onclick="showPopup('Key insight','Scalar multiplication changes only how far you travel along a fixed line — |k| sets the length, and the sign of k picks which of the two directions along that line you go.')">Key insight</button>
<span style="font-size:10px;color:#888;line-height:1.35">Hover or click any arrow for details.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var FW = 600, FH = 590;
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FW, FH).attr('preserveAspectRatio', 'xMidYMid meet');

var SQ10 = Math.sqrt(10);
var DX = 3 / SQ10, DY = -1 / SQ10;          // unit direction of v (screen coords, y down)
var PX = -DY, PY = DX;                      // perpendicular, pointing "below" the line
var VL = 165;                               // pixel length of reference vector v

var C = {
  navy: '#1a4a7f', orange: '#e8721c', teal: '#14969c',
  red: '#c8434e', live: '#7b3fa0', dot: '#000000'
};

var st = { k: 1, overlay: false, showK: true };

/* ───────── helpers ───────── */
function fmt(x) {
  var s = (Math.abs(x) < 1e-9 ? 0 : x).toFixed(2);
  return s.replace('-', '\u2212');
}

function fArrow(g, x1, y1, x2, y2, color, w, op) {
  var grp = g.group();
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy);
  op = (op == null) ? 1 : op;
  if (L < 1.2) {
    grp.circle(w * 2.4).center(x1, y1).fill({ color: color, opacity: op });
    return grp;
  }
  var ux = dx / L, uy = dy / L;
  var hl = Math.min(5.2 * w, L * 0.85), hw = 1.85 * w;
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  grp.line(x1, y1, bx + ux * hl * 0.45, by + uy * hl * 0.45)
    .stroke({ color: color, width: w, linecap: 'butt', opacity: op });
  var nx = -uy, ny = ux;
  grp.polygon([[x2, y2], [bx + nx * hw, by + ny * hw], [bx - nx * hw, by - ny * hw]])
    .fill({ color: color, opacity: op });
  grp.line(x1, y1, x2, y2).stroke({ color: '#fff', width: 16, opacity: 0 })
    .css('pointer-events', 'stroke');
  return grp;
}

function fLabel(g, str, cx, cy, size, color, italic) {
  var t = g.text(str);
  t.font({
    family: 'Georgia, "Times New Roman", serif', size: size, weight: 'bold',
    style: (italic === false ? 'normal' : 'italic'), anchor: 'middle', leading: 1
  });
  t.fill(color || '#111');
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  t.center(cx, cy);
  return t;
}

function fHalfV(g, cx, cy, size, color) {
  var grp = g.group();
  var num = grp.text('1').font({ family: 'Georgia, serif', size: size * 0.6, weight: 'bold', anchor: 'middle', leading: 1 }).fill(color);
  num.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
  num.center(cx, cy - size * 0.33);
  var den = grp.text('2').font({ family: 'Georgia, serif', size: size * 0.6, weight: 'bold', anchor: 'middle', leading: 1 }).fill(color);
  den.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
  den.center(cx, cy + size * 0.36);
  grp.line(cx - size * 0.27, cy, cx + size * 0.27, cy).stroke({ color: color, width: 1.5 });
  fLabel(grp, 'v', cx + size * 0.62, cy, size, color);
  return grp;
}

function attach(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

/* ───────── stacked view (faithful to the source figure) ───────── */
var STACK = [
  { k: 3, c: C.navy, tx: 12, ty: 210, lab: '3v',
    tip: '3v — three times as long as v, same direction',
    pop: ['3\u2009v', 'Multiplying v by k = 3 stretches the arrow to three times its length: |3v| = 3|v| \u2248 9.49. Because k is positive, the arrow keeps exactly the same heading and stays on the same line of action.'] },
  { k: 1, c: C.orange, tx: 12, ty: 320, lab: 'v',
    tip: 'v — the reference vector \u27e83, 1\u27e9',
    pop: ['v', 'This is the reference vector v = \u27e83, 1\u27e9 with magnitude \u221a10 \u2248 3.16. Every other arrow in the figure is a scalar multiple of this one, so they are all parallel.'] },
  { k: 0.5, c: C.teal, tx: 12, ty: 457, lab: 'half',
    tip: '\u00bdv — half as long, same direction',
    pop: ['\u00bd\u2009v', 'A scalar strictly between 0 and 1 shrinks the vector: \u00bdv is half as long as v, yet its direction is identical. Scaling never tilts the arrow.'] },
  { k: -1, c: C.red, tx: 185, ty: 505, lab: '\u2212v',
    tip: '\u2212v — same length as v, opposite direction',
    pop: ['\u2212v', 'k = \u22121 preserves the length but reverses the direction. \u2212v lies on the same line as v, pointing the opposite way — which is why its tail dot is at the right and its arrowhead at the lower left.'] }
];

function renderStacked(g) {
  var gLive = g.group(), gRef = g.group(), gLab = g.group();

  /* live kv arrow drawn behind the reference arrows, tail on v's dot */
  if (st.showK) {
    var ax = 12, ay = 320, k = st.k;
    var ex = ax + k * VL * DX, ey = ay + k * VL * DY;
    if (Math.abs(k) < 1e-6) {
      var ring = gLive.circle(14).center(ax, ay).fill('none').stroke({ color: C.live, width: 3 });
      fLabel(gLab, 'k\u2009v = 0', 74, 346, 16, C.live);
      attach(ring, 'k = 0 \u2192 the zero vector (a single point)',
        'k = 0', 'At k = 0 the arrow collapses to a single point at the tail: the zero vector 0 = \u27e80, 0\u27e9. It has zero length and no direction.');
    } else {
      var tx, ty, hx, hy;
      if (k > 0) { tx = ax; ty = ay; hx = ex; hy = ey; } else { tx = ex; ty = ey; hx = ax; hy = ay; }
      var la = fArrow(gLive, tx, ty, hx, hy, C.live, 6, 0.45);
      gLive.circle(9).center(tx, ty).fill({ color: C.live, opacity: 0.5 });
      var lx = (k > 0) ? hx + 14 : hx + 32;
      var ly = (k > 0) ? hy - 19 : hy + 21;
      fLabel(gLab, 'k\u2009v', lx, ly, 18, C.live);
      attach(la, 'k v with k = ' + fmt(st.k) + '  \u2192  |k v| = ' + fmt(Math.abs(st.k) * SQ10),
        'k\u2009v (live)', 'With k = ' + fmt(st.k) + ', k\u2009v = \u27e8' + fmt(3 * st.k) + ', ' + fmt(st.k) + '\u27e9 and |k\u2009v| = |k||v| = ' + fmt(Math.abs(st.k) * SQ10) + '. The arrow stays on v\u2019s line of action; only its length and its sense along that line change.');
    }
  }

  /* the four reference arrows */
  for (var i = 0; i < STACK.length; i++) {
    var s = STACK[i];
    var hx2 = s.tx + s.k * VL * DX, hy2 = s.ty + s.k * VL * DY;
    var a = fArrow(gRef, s.tx, s.ty, hx2, hy2, s.c, 3.4, 1);
    gRef.circle(9).center(s.tx, s.ty).fill(C.dot);
    attach(a, s.tip, s.pop[0], s.pop[1]);
    if (s.lab === '3v') fLabel(gLab, '3v', hx2 + 22, hy2 - 16, 22, '#111');
    else if (s.lab === 'v') fLabel(gLab, 'v', hx2 - 16, hy2 - 20, 22, '#111');
    else if (s.lab === 'half') fHalfV(gLab, hx2 - 20, hy2 - 22, 21, '#111');
    else fLabel(gLab, '\u2212v', s.tx + 26, s.ty + 4, 22, '#111');
  }
}

/* ───────── shared-tail overlay ───────── */
function renderOverlay(g) {
  var ox = 270, oy = 440, L = 85;
  var gGuide = g.group(), gBand = g.group(), gRef = g.group(), gHead = g.group(), gLab = g.group();

  var t1 = -(ox - 14) / DX, t2 = (FW - 14 - ox) / DX;
  var guide = gGuide.line(ox + t1 * DX, oy + t1 * DY, ox + t2 * DX, oy + t2 * DY)
    .stroke({ color: '#c4c4c4', width: 1.3, dasharray: '7,6' });
  attach(guide, 'Line of action: every scalar multiple of v lands on this line',
    'One line of action', 'All scalar multiples k\u2009v lie on a single straight line through the shared tail. Positive multiples occupy one ray, negative multiples the opposite ray.');

  for (var m = -3; m <= 3; m++) {
    if (m === 0) continue;
    var px = ox + m * L * DX, py = oy + m * L * DY;
    gGuide.line(px - PX * 5, py - PY * 5, px + PX * 5, py + PY * 5).stroke({ color: '#cfcfcf', width: 1.3 });
  }

  /* live kv as a translucent band behind the reference arrows */
  if (st.showK) {
    var k = st.k;
    var tipx = ox + k * L * DX, tipy = oy + k * L * DY;
    if (Math.abs(k) < 1e-6) {
      gHead.circle(15).center(ox, oy).fill('none').stroke({ color: C.live, width: 3 });
      fLabel(gLab, 'k\u2009v = 0', ox + 8 + PX * 34, oy + PY * 34, 16, C.live);
    } else {
      gBand.line(ox, oy, tipx, tipy).stroke({ color: C.live, width: 11, linecap: 'round', opacity: 0.3 });
      var lh = fArrow(gHead, ox + (tipx - ox) * 0.75, oy + (tipy - oy) * 0.75, tipx, tipy, C.live, 4, 0.85);
      attach(lh, 'k v with k = ' + fmt(k) + '  \u2192  |k v| = ' + fmt(Math.abs(k) * SQ10),
        'k\u2009v (live)', 'With k = ' + fmt(k) + ', the arrow reaches ' + fmt(Math.abs(k)) + ' \u00d7 |v| from the shared tail, on the ' + (k > 0 ? 'same ray as v' : 'opposite ray from v') + '.');
      fLabel(gLab, 'k\u2009v', tipx + PX * 28, tipy + PY * 28, 18, C.live);
    }
  }

  var OVL = [
    { k: 3, c: C.navy, lab: '3v', side: -1, tip: '3v — three times |v|, same ray' },
    { k: 1, c: C.orange, lab: 'v', side: -1, tip: 'v — the reference vector' },
    { k: 0.5, c: C.teal, lab: 'half', side: -1, tip: '\u00bdv — half of |v|, same ray' },
    { k: -1, c: C.red, lab: '\u2212v', side: -1, tip: '\u2212v — |v| long, opposite ray' }
  ];
  for (var i = 0; i < OVL.length; i++) {
    var s = OVL[i];
    var hx = ox + s.k * L * DX, hy = oy + s.k * L * DY;
    var a = fArrow(gRef, ox, oy, hx, hy, s.c, 4.5, 1);
    attach(a, s.tip, s.lab === 'half' ? '\u00bd\u2009v' : s.lab,
      'Drawn from the shared tail, this multiple ends ' + Math.abs(s.k) + ' \u00d7 |v| away, on the ' + (s.k > 0 ? 'positive' : 'negative') + ' ray of the same line.');
    var lx = hx + s.side * PX * 17, ly = hy + s.side * PY * 17;
    if (s.lab === '3v') fLabel(gLab, '3v', lx, ly, 21, '#111');
    else if (s.lab === 'v') fLabel(gLab, 'v', lx, ly, 21, '#111');
    else if (s.lab === 'half') fHalfV(gLab, lx - 6, ly - 2, 20, '#111');
    else fLabel(gLab, '\u2212v', lx - 6, ly - 2, 21, '#111');
  }

  var dot = gLab.circle(11).center(ox, oy).fill(C.dot);
  attach(dot, 'Shared tail: every multiple starts here',
    'Shared tail', 'Collapsing all four tails onto one point makes the common line of action explicit: scaling v never leaves this line.');
}

/* ───────── readout ───────── */
function renderReadout(g) {
  var k = st.k;
  var txt = 'k = ' + fmt(k) + '     k\u2009v = \u27e8' + fmt(3 * k) + ', ' + fmt(k) + '\u27e9     |k\u2009v| = |k||v| = ' + fmt(Math.abs(k) * SQ10);
  var t = g.text(txt).font({ family: 'Helvetica, Arial, sans-serif', size: 13, anchor: 'start' }).fill('#8f8f8f');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  t.move(14, 12);
}

function render() {
  figDraw.clear();
  figDraw.rect(FW, FH).fill('#ffffff');
  var gMain = figDraw.group();
  if (st.overlay) renderOverlay(gMain); else renderStacked(gMain);
  renderReadout(figDraw.group());
}

/* ───────── interaction handlers ───────── */
function update_scalarK(v) { st.k = +v; render(); }
function toggle_layoutMode(on) { st.overlay = !!on; render(); }
function toggle_showKArrow(on) { st.showK = !!on; render(); }

/* ───────── demo step player ───────── */
var demoSteps = [
  { title: 'The reference vector v',
    narration: 'Start with the orange arrow v and its three relatives stacked above and below it. Every arrow points along the same shallow upward slope, so only length and direction-sign differ.',
    state: { scalarK: 1, layoutMode: 'Stacked', showKArrow: true } },
  { title: 'Stretching: k = 3',
    narration: 'Drag k up to 3 and the live arrow grows to three times the length of v, matching the navy 3v arrow exactly — but its heading never changes.',
    state: { scalarK: 3, layoutMode: 'Stacked', showKArrow: true } },
  { title: 'Shrinking: k = \u00bd',
    narration: 'Pull k down to one half and the arrow contracts onto the teal \u00bdv. A scalar between 0 and 1 shortens the vector without tilting it.',
    state: { scalarK: 0.5, layoutMode: 'Stacked', showKArrow: true } },
  { title: 'Crossing zero',
    narration: 'At k = 0 the arrow shrinks to a single point at the tail — the zero vector. Nudging k just below zero makes the arrowhead pop out on the opposite side.',
    state: { scalarK: 0, layoutMode: 'Stacked', showKArrow: true } },
  { title: 'Reversing: k = \u22121',
    narration: 'At k = \u22121 the arrow has the same length as v but points down and to the left, matching the red \u2212v arrow. Negative scalars reverse direction along the same line.',
    state: { scalarK: -1, layoutMode: 'Stacked', showKArrow: true } },
  { title: 'Overlay: one line of action',
    narration: 'Switch to the shared-tail overlay: all the arrows now spring from one dot. Positive multiples stack along one ray, the negative multiple lies on the opposite ray — every scalar multiple of v lives on a single line.',
    state: { scalarK: -2, layoutMode: 'Shared tail overlay', showKArrow: true } }
];
var curStep = 0;

function applyStep(i) {
  curStep = (i % demoSteps.length + demoSteps.length) % demoSteps.length;
  var s = demoSteps[curStep];
  var kIn = document.getElementById('scalarKInput');
  kIn.value = s.state.scalarK;
  document.getElementById('scalarKVal').value = (+s.state.scalarK).toFixed(2);
  st.k = +s.state.scalarK;
  var lay = document.getElementById('layoutModeInput');
  var ov = (s.state.layoutMode === 'Shared tail overlay');
  lay.checked = ov; st.overlay = ov;
  var sk = document.getElementById('showKArrowInput');
  sk.checked = !!s.state.showKArrow; st.showK = !!s.state.showKArrow;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + demoSteps.length + ' \u00b7 ' + s.title;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

